const root='/Users/tamastyukodi/Development/video-platform-ui';
const axiosModule=require('/Users/tamastyukodi/Development/video-platform-ui/node_modules/axios');
const axios=axiosModule.default;
const identity=new URLSearchParams(window.location.search).get('qaRole') || 'CREATOR';
const fixtureCount=Number(new URLSearchParams(window.location.search).get('qaCount')||'0');
if(![0,1,99,100].includes(fixtureCount))throw new Error('Unsupported collection fixture');
const items=Array.from({length:fixtureCount},(_,i)=>({id:`qa-menu-${String(i+1).padStart(3,'0')}`,title:`QA menu item ${String(i+1).padStart(3,'0')}`,type:'COURSE',price:10,pricingModel:'ONE_TIME',currency:'EUR',status:'PUBLISHED',createdById:'qa-menu-owner'}));
localStorage.setItem('cart:v1',JSON.stringify({products:items,total:fixtureCount*10,loading:false}));
localStorage.setItem('wishlist:v1',JSON.stringify(items));
const events=[];
let capturedAdapter;
const guard=async config=>{
 events.push({transport:'axios-guard',method:config.method,url:config.url,role:identity,status:config.url==='api/user/userInfo'?(identity==='GUEST'?401:200):503});
 renderEvents();
 if(config.url==='api/user/userInfo' && identity!=='GUEST')return {status:200,statusText:'OK',data:{id:'qa-boundary-identity',firstName:'Boundary',lastName:'Fixture',email:'boundary@example.test',roles:[identity],onboardingCompleted:true},headers:{},config};
 const status=config.url==='api/user/userInfo' && identity==='GUEST'?401:503;
 throw new axiosModule.AxiosError('Blocked by isolated QA transport','QA_NETWORK_DENIED',config,null,{status,statusText:'QA captured',data:{message:'No real network allowed'},headers:{},config});
};
axios.defaults.adapter=guard;
window.fetch=async(url,options)=>{events.push({transport:'fetch-guard',method:options?.method||'GET',url:String(url),role:identity});renderEvents();throw new Error('QA_NETWORK_DENIED: storage PUT captured locally');};
function renderEvents(){const out=document.getElementById('qa-boundary-events');if(out)out.textContent=JSON.stringify(events,null,2);}
const panel=document.createElement('section');panel.setAttribute('aria-label','Isolated collection fixture');panel.style.cssText='padding:8px;background:white;color:black;font:14px sans-serif';
panel.textContent=`Isolated collection fixture; build: ${process.env.NODE_ENV}; identity: ${identity}; seeded collection count: ${fixtureCount}; shared-client requests denied except synthetic profile`;
const output=document.createElement('pre');output.id='qa-boundary-events';output.setAttribute('aria-label','Captured local requests');panel.appendChild(output);document.body.prepend(panel);
import('/Users/tamastyukodi/Development/video-platform-ui/src/index.tsx');
